import sys
from collections import Counter

def can_form_palindrome(s):
    count = Counter(s)
    odd_count_chars = [char for char, cnt in count.items() if cnt % 2 != 0]
    return len(odd_count_chars) <= 1

def construct_palindrome_permutation(s):
    if not can_form_palindrome(s):
        return -1

    count = Counter(s)
    half_palindrome = []
    middle_char = ''

    for char in sorted(count):
        if count[char] % 2 != 0:
            middle_char = char
        half_palindrome.extend([char] * (count[char] // 2))

    full_palindrome = half_palindrome + [middle_char] + half_palindrome[::-1]
    char_to_indices = {char: [] for char in set(s)}

    for index, char in enumerate(s):
        char_to_indices[char].append(index + 1)

    permutation = []
    for char in full_palindrome:
        permutation.append(char_to_indices[char].pop())

    return permutation

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    T = int(input[index])
    index += 1
    results = []
    for _ in range(T):
        s = input[index]
        index += 1
        result = construct_palindrome_permutation(s)
        if result == -1:
            results.append('-1')
        else:
            results.append(' '.join(map(str, result)))
    print('\n'.join(results))

if __name__ == "__main__":
    main()
